// no daily limit: the pay slows down within an hour (public/shared/earn.js). Label and note for the page
function paceLabel(p){const he=I18N.lang==="he";if(!p)return "";const pc=Math.round(p.factor*100);return pc>=100?(he?"מלא":"Full pay"):(he?`${pc}% מהרגיל`:`${pc}% of normal`);}
function paceNote(p){const he=I18N.lang==="he";if(!p||p.factor>=1)return he?"תמשיכו לשחק כמה שרוצים!":"Keep playing as much as you like!";
  const m=p.resetAt?Math.max(1,Math.ceil((p.resetAt-Date.now())/60000)):60,pc=Math.round(p.factor*100);
  return he?`הרווחתם הרבה בשעה האחרונה, אז עכשיו מקבלים ${pc}% מהרגיל. בעוד ${m} דקות זה חוזר למלא.`:`You've earned a lot this hour, so you now get ${pc}% of the normal coins. Full pay is back in ${m} min.`;}
