  MG={game:id,state:"menu",score:0,keys:{},demo:mgDemoInit(id),parts:[],fx:[],shake:0,flash:0};
  mgOverlay.style.setProperty("--mg",info.color);mgOverlay.style.setProperty("--mgd",info.dark);mgOverlay.style.setProperty("--mgbg",info.bg);
