  $mg("mgTitle").dir=/[\u0590-\u05FF]/.test(I18N.T(info.title))?"rtl":"ltr";$mg("mgTitle").innerHTML=[...I18N.T(info.title)].map((ch,i)=>ch===" "?'<span class="sp"> </span>':`<span style="--i:${i}">${ch}</span>`).join("");
