  $mg("mgScore").textContent="0";$mg("mgTime").textContent=id==="dig"?"10":"30";
  {const fut=G.world==="future";$mg("mgClose").querySelector("span").textContent=I18N.T(fut?"BACK":"PLAZA");$mg("mgClose").setAttribute("aria-label",I18N.T(fut?"Back to the city":"Back to the Plaza"));$mg("mgQuit").textContent=I18N.T(fut?"Back to the city":"Back to the Plaza");}
