function paintMgStatus(){if(!MG)return;const st=mgStatus,best=st&&st.best?st.best[MG.game]||0:0;
  $mg("mgBest").textContent=best.toLocaleString("en-US");
  $mg("mgLeft").textContent=st&&st.pace?paceLabel(st.pace):"…";}
var closeMinigame=function(){if(mgOverlay.hidden)return;const round=MG;mgOverlay.hidden=true;body.classList.remove("mg-open");MG=null;nearStation=null;$mg("mgCount").hidden=true;
  if(round&&round.state==="play"&&round.id){round.state="left";finishRound(round).then(r=>showRoundResult(round,r));}
  else{if(round)round.state="closed";sfx.close();}}
