function showRoundResult(round,r){
  if(!r.ok){showResult(MG_INFO[round.game].title,r.data.error||"Couldn't save this round.",0);sfx.error();return;}
  setMyCoins(r.data.total);showResult(MG_INFO[round.game].title,`${r.data.score} ${r.data.score===1?"point":"points"}`,r.data.coins);
  if(r.data.coins>0){sfx.success();coinRain(Math.min(20,6+r.data.coins));}}
