// while the window is open, keys belong to the game, not the world
addEventListener("keydown",e=>{if(mgOverlay.hidden)return;e.stopImmediatePropagation();
  if(e.key==="Escape"){closeMinigame();return;}
  if(MG&&MG.state==="play"&&MG.game==="flap"&&(e.code==="Space"||e.code==="ArrowUp"||e.code==="KeyW")){e.preventDefault();if(!e.repeat)flapUp();return;}
  if(MG&&MG.state==="play"&&MG.game==="rooftops"&&(e.code==="Space"||e.code==="ArrowUp"||e.code==="KeyW")){e.preventDefault();if(!e.repeat)hopJump();return;}
  if(MG&&MG.state==="play"&&MG.game==="robot"){const n={Digit1:0,Digit2:1,Digit3:2,Numpad1:0,Numpad2:1,Numpad3:2,KeyJ:0,KeyK:1,KeyL:2}[e.code];if(n!==undefined){e.preventDefault();if(!e.repeat)robotFix(n);return;}}
  if(MG&&(MG.state==="menu")&&(e.code==="Space"||e.code==="Enter")&&document.activeElement===document.body){e.preventDefault();startCountdown();return;}
  if(MG&&MG.keys&&["ArrowLeft","ArrowRight","KeyA","KeyD"].includes(e.code)){MG.keys[e.code]=true;e.preventDefault();}},true);
addEventListener("keyup",e=>{if(MG&&MG.keys)MG.keys[e.code]=false;},true);

