function tutArt(kind){
  const W=200,H=140,cv=document.createElement("canvas");cv.width=W;cv.height=H;const c=cv.getContext("2d");
  const g=c.createLinearGradient(0,0,0,H);g.addColorStop(0,"#ffffff");g.addColorStop(1,"#e6f2ff");c.fillStyle=g;c.fillRect(0,0,W,H);
  const [a,b]=kind.split(":");c.save();c.translate(W/2,H/2);
  if(a==="fruit"){drawFruit(c,FRUITS.find(f=>f.k===b),0,6,1.6);}
  else if(a==="shell"){drawShellThing(c,{k:b,x:0,y:10},1.1);}
  else if(a==="dig"){if(b==="hint"){c.fillStyle="#8a5a2a";c.beginPath();c.ellipse(0,20,40,15,0,0,7);c.fill();c.font='54px "HeeboDisplay","Lilita One", sans-serif';c.textAlign="center";c.textBaseline="middle";c.lineWidth=8;c.strokeStyle="#5a3410";c.strokeText("2",0,2);c.fillStyle="#ff8a1c";c.fillText("2",0,2);}
    else drawDigItem(c,b,0,4,1.5);}
  else if(a==="move"){drawBasket(c,0,24);drawMiniJumpi(c,0,0,.8,skinHex(),0);arrows(c);}
  else if(a==="tap"||a==="dig"&&!b){drawHand(c,8,6);}
  else if(a==="flap"){drawFlapJumpi(c,-10,4,1.25,-.3,1);drawHand(c,46,30,.7);}
  else if(a==="board"){drawBoard(c,-60,-28,50,"#ff5fa8",true,[-80,80]);drawBoard(c,-60,34,50,"#1fb6ff",false,[-80,80]);drawFlapJumpi(c,40,2,.9,0,0);c.strokeStyle="#ff5fa8";c.lineWidth=4;c.setLineDash([6,6]);c.beginPath();c.moveTo(-90,4);c.lineTo(10,4);c.stroke();c.setLineDash([]);}
  else if(a==="gshell"){drawGoldShell(c,0,4,1.6,0);}
  else if(a==="dmove"){c.fillStyle="#141a3d";c.fillRect(-100,-70,200,140);drawDrone(c,0,10,0,0,.9);arrows(c);}
  else if(a==="dring"||a==="dgold"){c.fillStyle="#141a3d";c.fillRect(-100,-70,200,140);drawRing(c,0,-14,a==="dgold",0,1.2);drawDrone(c,0,36,0,0,.6);}
  else if(a==="dstorm"){c.fillStyle="#141a3d";c.fillRect(-100,-70,200,140);drawStorm(c,0,-16,0,1.3);}
  else if(a==="rzone"||a==="rgold"||a==="rok"){c.fillStyle="#2d2a6b";c.fillRect(-100,-70,200,140);c.scale(.62,.62);c.translate(0,40);
    if(a==="rzone"){c.fillStyle="rgba(125,255,155,.25)";c.fillRect(-80,-110,160,150);}drawRobot(c,a==="rzone"?-10:0,0,{k:a==="rgold"?"gold":a==="rok"?"ok":"bot",need:1,fixed:a==="rgold"},0);}
  else if(a==="rparts"){R_PARTS.forEach((p,i)=>drawPart(c,p.k,-60+i*60,0,1.2));}
  else if(a==="hjump"||a==="hgap"||a==="hstar"||a==="hfall"){c.fillStyle="#7a5bff";c.fillRect(-100,-70,200,140);c.save();c.translate(-100,-200);c.scale(.5,.5);drawRoof(c,0,150,400,0);drawRoof(c,(a==="hfall"?300:250),180,a==="hfall"?330:380,1);c.restore();
    if(a==="hstar")drawStar(c,0,-30,0,1.2);drawRunner(c,a==="hfall"?10:-40,a==="hfall"?40:-6,0,a!=="hfall",a==="hfall");if(a==="hjump")drawHand(c,50,30,.7);}
  else if(a==="crash"){drawBoard(c,8,-24,60,"#2fd36b",false,[-80,80]);drawFlapJumpi(c,-30,-4,1,.6,0,true);c.fillStyle="#ffd23a";[[-6,-34],[4,-22],[-14,-20]].forEach(([x,y])=>{c.beginPath();c.arc(x,y,4,0,7);c.fill();});}
  c.restore();
  if(a==="dig"&&!b){c.save();c.translate(W/2,H/2);drawHand(c,8,6);c.restore();}
  return cv.toDataURL();
}
function arrows(c){c.fillStyle="#1f9bff";[-1,1].forEach(s=>{c.beginPath();c.moveTo(s*86,0);c.lineTo(s*66,-14);c.lineTo(s*66,14);c.closePath();c.fill();});}
function drawHand(c,x,y,s=1){c.save();c.translate(x,y);c.scale(s,s);c.fillStyle="#ffe0c2";c.strokeStyle="#c98a5a";c.lineWidth=3;
  c.beginPath();c.roundRect(-8,-34,16,40,8);c.fill();c.stroke();c.beginPath();c.roundRect(-22,0,44,36,14);c.fill();c.stroke();
  c.strokeStyle="#1f9bff";c.lineWidth=4;c.beginPath();c.arc(0,-40,14,Math.PI*1.1,Math.PI*1.9);c.stroke();c.beginPath();c.arc(0,-40,24,Math.PI*1.15,Math.PI*1.85);c.stroke();c.restore();}

/* ----- 3, 2, 1, GO! then play ----- */
async function startCountdown(){
  if(!MG||MG.state==="starting"||MG.state==="count")return;const game=MG.game,round=MG;
  round.state="starting";mgShow(null);sfx.whoosh();
  const req=api("/api/minigame/start",{game});
  const el=$mg("mgCount");el.hidden=false;
  for(const n of ["3","2","1","GO!"]){if(MG!==round)return;el.textContent=n;el.classList.remove("pop");void el.offsetWidth;el.classList.add("pop");
    n==="GO!"?sfx.success():sfx.tick(true);if(n!=="GO!")await new Promise(r=>setTimeout(r,650));}
  const r=await req;
  setTimeout(()=>{el.hidden=true;},450);
  if(MG!==round)return;
  if(!r.ok){toast(r.data.error||"Couldn't start the game.");sfx.error();round.state="menu";mgShow("mgStart");return;}
  Object.assign(round,{id:r.data.id,state:"play",score:0,raw:0,caught:[],passed:0,keys:{},t0:performance.now(),last:performance.now(),info:r.data,fx:[],parts:[],shake:0});
  $mg("mgScore").textContent="0";
  ({fruit:fruitInit,shell:shellInit,dig:digInit,flap:flapInit,drone:droneInit,robot:robotInit,rooftops:hopInit})[game]();
}
function mgLoop(now){
  if(!MG||mgOverlay.hidden)return;requestAnimationFrame(mgLoop);
  const dt=Math.min(.05,(now-(MG.last||now))/1000);MG.last=now;const T=now/1000;
  mgFit();mgBegin();
  if(MG.state==="play"){
    const t=(now-MG.t0)/1000;
    if(MG.game==="fruit"||MG.game==="shell"||MG.game==="drone"||MG.game==="robot"){const left=Math.max(0,(MG.info.secs||30)-t);$mg("mgTime").textContent=Math.ceil(left);if(left<=0){endRound();}}
    ({fruit:fruitTick,shell:shellTick,dig:digTick,flap:flapTick,drone:droneTick,robot:robotTick,rooftops:hopTick})[MG.game](dt,t);
  }else mgDemo(dt,T);
  partsTick(dt);drawFx(dt);
  if(MG.flash>0){MG.flash-=dt;mg2d.fillStyle=`rgba(255,255,255,${Math.max(0,MG.flash*2)})`;mg2d.fillRect(X0(),Y0(),VW(),VH());}
}
async function endRound(){
  if(!MG||MG.state!=="play")return;MG.state="ending";const round=MG;
  const r=await finishRound(round);
  if(MG!==round){showRoundResult(round,r);return;}round.state="over";
  const coins=r.ok?r.data.coins:0,score=r.ok?r.data.score:round.score,info=MG_INFO[round.game];
  if(r.ok){mgStatus={...(mgStatus||{best:{}}),todayEarned:r.data.todayEarned,pace:r.data.pace};mgStatus.best={...(mgStatus.best||{}),[round.game]:r.data.best};}
  // the result card: the score counts up, stars pop in, coins
  const stars=info.stars.filter(s=>score>=s).length;
  $mg("mgStars").innerHTML=[0,1,2].map(i=>`<i class="${i<stars?"on":""}" style="--i:${i}"></i>`).join("");
  $mg("mgNewBest").hidden=!(r.ok&&r.data.newBest);
  $mg("mgWon").textContent="+"+coins;
    $mg("mgNote").textContent=!r.ok?(r.data.error||"Couldn't save this round."):
    paceNote(r.data.pace);
  $mg("mgEndTitle").textContent=round.game==="flap"&&round.crashed?"OUCH!":stars===3?"AMAZING!":stars===2?"GREAT JOB!":stars===1?"NICE!":"GOOD TRY!";
  mgShow("mgEnd");const fin=$mg("mgFinal");const t0=performance.now();
  (function count(){const k=Math.min(1,(performance.now()-t0)/700);fin.textContent=Math.round(score*k).toLocaleString("en-US");if(k<1&&MG===round)requestAnimationFrame(count);})();
  if(r.ok){setMyCoins(r.data.total);if(coins>0){sfx.success();coinRain(Math.min(20,6+coins));}else sfx.close();}else sfx.error();
  setTimeout(()=>$mg("mgAgain").focus(),60);
}
function addScore(n,x,y){if(!MG)return;MG.raw+=n;MG.score=Math.max(0,MG.raw);$mg("mgScore").textContent=MG.score;bumpHud();
  MG.fx.push({x,y,text:(n>0?"+":"")+n,col:n>0?"#ffffff":"#ff4f4f",t:0});if(n<0){MG.shake=.3;sfx.error();}else{sfx.tick(true);burst(x,y,n>=3?"#ffd23a":"#ffffff",n>=3?16:9);}}
function bumpHud(){const b=$mg("mgHudScore");b.classList.remove("bump");void b.offsetWidth;b.classList.add("bump");}
function drawFx(dt){const c=mg2d;for(let i=MG.fx.length-1;i>=0;i--){const f=MG.fx[i];f.t+=dt;if(f.t>.8){MG.fx.splice(i,1);continue;}
  const k=f.t<.12?f.t/.12:1;c.save();c.globalAlpha=1-Math.max(0,f.t-.4)/.4;c.translate(f.x,f.y-f.t*70);c.scale(.6+k*.6,.6+k*.6);c.font='40px "HeeboDisplay","Lilita One", sans-serif';c.textAlign="center";c.lineJoin="round";c.lineWidth=8;c.strokeStyle="#16264f";
  c.strokeText(f.text,0,0);c.fillStyle=f.col;c.fillText(f.text,0,0);c.restore();}}
// little sparkles / sand puffs
function burst(x,y,col,n=10,spd=180,grav=300,size=5){if(!MG)return;for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,v=spd*(.4+Math.random()*.8);MG.parts.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-spd*.4,g:grav,t:0,life:.5+Math.random()*.4,col,s:size*(.6+Math.random()*.8),star:col==="#ffd23a"||col==="#ffffff"});}}
function partsTick(dt){const c=mg2d;for(let i=MG.parts.length-1;i>=0;i--){const p=MG.parts[i];p.t+=dt;if(p.t>p.life){MG.parts.splice(i,1);continue;}
  p.vy+=p.g*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;c.globalAlpha=1-p.t/p.life;c.fillStyle=p.col;
  if(p.star){c.save();c.translate(p.x,p.y);c.rotate(p.t*6);c.beginPath();for(let k=0;k<8;k++){const r=k%2?p.s*.4:p.s*1.2,a=k*Math.PI/4;c.lineTo(Math.cos(a)*r,Math.sin(a)*r);}c.fill();c.restore();}
  else{c.beginPath();c.arc(p.x,p.y,p.s,0,7);c.fill();}}c.globalAlpha=1;}
// pointer → play-area coordinates
function mgPoint(e){return [e.clientX/MV.s-MV.ox,e.clientY/MV.s-MV.oy];}
mgCanvas.addEventListener("pointermove",e=>{if(MG&&MG.state==="play"&&MG.game==="fruit")MG.target=mgPoint(e)[0];});
mgCanvas.addEventListener("pointerdown",e=>{if(!MG||MG.state!=="play")return;const [x,y]=mgPoint(e);
  if(MG.game==="fruit")MG.target=x;else if(MG.game==="shell")shellTap(x,y);else if(MG.game==="flap")flapUp();else if(MG.game==="rooftops")hopJump();else if(MG.game==="drone")droneTap(x);else if(MG.game==="robot")robotTap(x,y);else digTap(x,y);});

/* ---------- shared scenery ---------- */
function rr2(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}
function skyFill(c,top,bot,y1=MH){const g=c.createLinearGradient(0,Y0(),0,y1);g.addColorStop(0,top);g.addColorStop(1,bot);c.fillStyle=g;c.fillRect(X0(),Y0(),VW(),y1-Y0()+2);}
function sun(c,x,y,r,t){const g=c.createRadialGradient(x,y,r*.4,x,y,r*2.6);g.addColorStop(0,"rgba(255,244,190,.9)");g.addColorStop(1,"rgba(255,244,190,0)");c.fillStyle=g;c.beginPath();c.arc(x,y,r*2.6,0,7);c.fill();
  c.save();c.translate(x,y);c.rotate(t*.15);c.fillStyle="rgba(255,236,150,.45)";for(let k=0;k<12;k++){c.rotate(Math.PI/6);c.beginPath();c.moveTo(r*1.1,-6);c.lineTo(r*1.8,0);c.lineTo(r*1.1,6);c.fill();}c.restore();
  c.fillStyle="#ffe066";c.beginPath();c.arc(x,y,r,0,7);c.fill();c.fillStyle="#fff3a8";c.beginPath();c.arc(x-r*.3,y-r*.3,r*.45,0,7);c.fill();}
function cloud(c,x,y,s){c.fillStyle="rgba(255,255,255,.95)";c.beginPath();c.arc(x,y,22*s,0,7);c.arc(x+26*s,y-12*s,28*s,0,7);c.arc(x+56*s,y,22*s,0,7);c.arc(x+28*s,y+6*s,22*s,0,7);c.fill();
  c.fillStyle="rgba(200,225,255,.6)";c.beginPath();c.ellipse(x+28*s,y+16*s,46*s,8*s,0,0,7);c.fill();}
function clouds(c,t,speed=12,y0=40,n=6){const span=VW()+300;for(let i=0;i<n;i++){const x=X0()-150+((i*263+t*speed*(1+i%3*.3))%span),y=Y0()+y0+((i*71)%90);cloud(c,x,y,.7+(i%3)*.25);}}
// a little 2D Jumpi (used by the basket, the tutorials and Jumpi Flap)
function drawMiniJumpi(c,x,y,s,col,look=0){c.save();c.translate(x,y);c.scale(s,s);
  c.fillStyle=col;c.beginPath();c.ellipse(0,-44,34,31,0,0,7);c.fill();
  c.fillStyle="rgba(255,255,255,.25)";c.beginPath();c.ellipse(-12,-58,10,6,-.5,0,7);c.fill();
  [-1,1].forEach(sx=>{c.fillStyle="#fff";c.beginPath();c.ellipse(sx*12,-44,10,12,0,0,7);c.fill();c.fillStyle="#1d2b4f";c.beginPath();c.arc(sx*12+look*3,-42,5.5,0,7);c.fill();c.fillStyle="#fff";c.beginPath();c.arc(sx*12+look*3+2,-45,2,0,7);c.fill();});
  c.strokeStyle="rgba(0,0,0,.45)";c.lineWidth=2.5;c.lineCap="round";c.beginPath();c.arc(0,-30,6,.2,Math.PI-.2);c.stroke();c.restore();}

/* ---------- FRUIT CATCH (the orchard) ---------- */
const FRUITS=[{k:"apple",col:"#ff3b3b",pts:1,w:34},{k:"pear",col:"#9ad13a",pts:1,w:22},{k:"orange",col:"#ff9a1f",pts:1,w:22},{k:"gold",col:"#ffd23a",pts:3,w:8},{k:"rotten",col:"#7a5a2a",pts:-2,w:16}];
function fruitInit(){Object.assign(MG,{bx:MW/2,target:MW/2,items:[],next:0,wob:0});}
function orchardTree(c,x,y,s,t){c.fillStyle="#8a5a34";rr2(c,x-10*s,y-70*s,20*s,74*s,6*s);c.fill();
  const sway=Math.sin(t*1.2+x*.01)*3;["#3fae4a","#4fc25a","#2f9a43"].forEach((col,k)=>{c.fillStyle=col;c.beginPath();c.arc(x+sway+(k-1)*26*s,y-92*s-(k===1?16*s:0),36*s,0,7);c.fill();});
  c.fillStyle="#ff4f4f";for(let k=0;k<4;k++){c.beginPath();c.arc(x+sway+(k*23%50-25)*s,y-(88+k*9%30)*s,5*s,0,7);c.fill();}}
function fruitScene(t){const c=mg2d;
  skyFill(c,"#7fd0ff","#d9f4ff",MH-60);sun(c,MW-90,Y0()+90,34,t);clouds(c,t,10,30,6);
  // rolling hills (far → near)
  [["#a6e08f",MH-90,140,.6],["#86d272",MH-60,120,.9]].forEach(([col,yy,amp,sp])=>{c.fillStyle=col;c.beginPath();c.moveTo(X0(),VH()+Y0());
    for(let x=X0();x<=X0()+VW()+20;x+=20)c.lineTo(x,yy-Math.sin(x*.006*sp+1)*amp*.3-amp*.2);c.lineTo(X0()+VW(),VH()+Y0());c.closePath();c.fill();});
  for(let x=X0()-40;x<X0()+VW()+80;x+=150)orchardTree(c,x+((x*7)%60),MH-70,.85,t);
  // fence and grass
  c.fillStyle="#fff7e6";for(let x=X0()-20;x<X0()+VW()+40;x+=34){rr2(c,x,MH-78,12,40,4);c.fill();}c.fillRect(X0(),MH-68,VW(),7);c.fillRect(X0(),MH-52,VW(),7);
  c.fillStyle="#5fbf4f";c.fillRect(X0(),MH-40,VW(),VH()+Y0()-MH+40);c.fillStyle="#4fae40";c.fillRect(X0(),MH-40,VW(),6);
  for(let x=X0();x<X0()+VW();x+=46){c.fillStyle=["#ff7fbf","#ffd23a","#ffffff"][Math.abs(x|0)%3];c.beginPath();c.arc(x+(x*13%30),MH-18+(x*7%14),4,0,7);c.fill();}
  // leafy canopy at the top, where the fruit falls from
  for(let x=X0()-60;x<X0()+VW()+80;x+=70){const k=Math.abs(Math.round(x/70))%2;c.fillStyle=k?"#3fae4a":"#4fc25a";c.beginPath();c.arc(x,Y0()-14+Math.sin(t+x)*2,70,0,7);c.fill();}
  c.fillStyle="#2f9a43";for(let x=X0()-30;x<X0()+VW()+60;x+=70){c.beginPath();c.arc(x,Y0()+30,22,0,7);c.fill();}
}
function drawFruit(c,f,x,y,s=1,rot=0){c.save();c.translate(x,y);c.scale(s,s);c.rotate(rot);
  c.fillStyle="rgba(0,0,0,.12)";c.beginPath();c.ellipse(3,22,16,4,0,0,7);c.fill();
  if(f.k==="pear"){c.fillStyle=f.col;c.beginPath();c.ellipse(0,6,18,20,0,0,7);c.fill();c.beginPath();c.ellipse(0,-10,12,13,0,0,7);c.fill();}
  else{const g=c.createRadialGradient(-7,-7,3,0,0,22);g.addColorStop(0,f.k==="gold"?"#fff6b0":"#ffffff");g.addColorStop(.25,f.col);g.addColorStop(1,f.k==="rotten"?"#4d3818":new THREE.Color(f.col).multiplyScalar(.7).getStyle());c.fillStyle=g;c.beginPath();c.arc(0,0,20,0,7);c.fill();}
  if(f.k==="rotten"){c.fillStyle="#4d3818";for(const [a,b,r] of[[-7,-4,5],[6,5,4],[2,-9,3]]){c.beginPath();c.arc(a,b,r,0,7);c.fill();}
    c.strokeStyle="rgba(120,160,60,.7)";c.lineWidth=2;for(let k=0;k<3;k++){c.beginPath();c.moveTo(-8+k*8,-24);c.quadraticCurveTo(-4+k*8,-32,-8+k*8,-40);c.stroke();}}
  if(f.k==="orange"){c.fillStyle="rgba(0,0,0,.08)";for(let i=0;i<5;i++){c.beginPath();c.arc(-8+i*4,4,1.5,0,7);c.fill();}}
  c.strokeStyle="#6b4a2a";c.lineWidth=4;c.lineCap="round";c.beginPath();c.moveTo(0,-18);c.lineTo(2,-27);c.stroke();
  c.fillStyle="#3fbf4f";c.beginPath();c.ellipse(9,-25,9,4.5,-.5,0,7);c.fill();
  c.fillStyle="rgba(255,255,255,.55)";c.beginPath();c.ellipse(-7,-7,5,8,.5,0,7);c.fill();
  if(f.k==="gold"){c.strokeStyle="rgba(255,255,255,.9)";c.lineWidth=3;const tw=(performance.now()/300)%(Math.PI*2);for(let i=0;i<4;i++){const a=i*Math.PI/2+tw*.3;c.beginPath();c.moveTo(Math.cos(a)*26,Math.sin(a)*26);c.lineTo(Math.cos(a)*34,Math.sin(a)*34);c.stroke();}}
  c.restore();}
function drawBasket(c,x,y,wob=0){c.save();c.translate(x,y);c.rotate(wob*.05);
  c.fillStyle="rgba(0,0,0,.15)";c.beginPath();c.ellipse(0,44,56,8,0,0,7);c.fill();
  c.strokeStyle="#8a5a34";c.lineWidth=7;c.beginPath();c.arc(0,-6,46,Math.PI*1.05,Math.PI*1.95);c.stroke();
  c.fillStyle="#c98a4f";c.beginPath();c.moveTo(-64,-8);c.lineTo(64,-8);c.lineTo(48,40);c.lineTo(-48,40);c.closePath();c.fill();
  c.strokeStyle="#a86c35";c.lineWidth=3;for(let i=0;i<4;i++){c.beginPath();c.moveTo(-60+i*2,4+i*10);c.lineTo(60-i*2,4+i*10);c.stroke();}
  for(let i=-3;i<=3;i++){c.beginPath();c.moveTo(i*17,-8);c.lineTo(i*13,40);c.stroke();}
  c.fillStyle="#e0a868";rr2(c,-70,-16,140,14,7);c.fill();c.fillStyle="#ff5f8f";rr2(c,-14,-18,28,10,5);c.fill();c.restore();}
function fruitTick(dt,t){const c=mg2d;
  if(MG.keys.ArrowLeft||MG.keys.KeyA)MG.target=MG.bx-420*dt*3;if(MG.keys.ArrowRight||MG.keys.KeyD)MG.target=MG.bx+420*dt*3;
  MG.target=Math.max(70,Math.min(MW-70,MG.target));const ob=MG.bx;MG.bx+=(MG.target-MG.bx)*Math.min(1,dt*14);MG.wob+=((MG.bx-ob)/Math.max(dt,.001)*.01-MG.wob)*Math.min(1,dt*8);
  const S=MG.info.items;while(MG.next<S.length&&S[MG.next].t<=t){const s=S[MG.next++];MG.items.push({id:s.i,f:FRUITS.find(f=>f.k===s.k)||FRUITS[0],x:s.x,y:20+(t-s.t)*s.v,vy:s.v,rot:0,spin:(Math.random()-.5)*3});}
  const by=MH-78;
  for(let i=MG.items.length-1;i>=0;i--){const it=MG.items[i];it.y+=it.vy*dt;it.rot+=dt*it.spin;
    if(it.y>by-14&&it.y<by+16&&Math.abs(it.x-MG.bx)<66){MG.caught.push(it.id);addScore(it.f.pts,it.x,by-30);if(it.f.k==="rotten")burst(it.x,by-10,"#6b5a2a",12,160,400,6);MG.items.splice(i,1);continue;}
    if(it.y>MH-30&&!it.landed){it.landed=true;burst(it.x,MH-30,"#9fdc7f",6,120,500,4);}
    if(it.y>MH+30)MG.items.splice(i,1);}
  const sh=MG.shake>0?(MG.shake-=dt,Math.sin(t*90)*8):0;
  c.save();c.translate(sh,0);fruitScene(t);for(const it of MG.items)drawFruit(c,it.f,it.x,it.y,1,it.rot);
  drawMiniJumpi(c,MG.bx,by+6,.95,skinHex(),Math.max(-1,Math.min(1,MG.wob)));drawBasket(c,MG.bx,by,MG.wob);c.restore();
}

/* ---------- SHELL SNAP (the beach) ---------- */
const HOLES=[];for(let r=0;r<3;r++)for(let q=0;q<4;q++)HOLES.push([120+q*160+(r%2?40:-20),210+r*92]);
function shellInit(){Object.assign(MG,{pops:[],next:0});}
function palmLeaves(c,x,y,flip,t){c.save();c.translate(x,y);c.scale(flip,1);for(let k=0;k<6;k++){c.save();c.rotate(.2+k*.32+Math.sin(t*1.3+k)*.04);c.fillStyle=k%2?"#2f9a43":"#3fbf55";
  c.beginPath();c.moveTo(0,0);c.quadraticCurveTo(80,-30,170,10);c.quadraticCurveTo(90,0,0,10);c.fill();c.restore();}c.restore();}
function shellScene(t){const c=mg2d;
  skyFill(c,"#4fb8ff","#bfe9ff",130);sun(c,MW-120,Y0()+60,28,t);clouds(c,t,8,10,4);
  const g=c.createLinearGradient(0,90,0,170);g.addColorStop(0,"#1f8fe0");g.addColorStop(1,"#4fd0ff");c.fillStyle=g;c.fillRect(X0(),100,VW(),80);
  c.strokeStyle="rgba(255,255,255,.5)";c.lineWidth=2;for(let k=0;k<5;k++){c.beginPath();for(let x=X0();x<=X0()+VW();x+=18)c.lineTo(x,112+k*12+Math.sin(x*.05+t*2+k)*2);c.stroke();}
  c.fillStyle="#f2d79b";c.fillRect(X0(),150,VW(),VH()+Y0()-150);
  c.fillStyle="rgba(255,255,255,.9)";c.beginPath();c.moveTo(X0(),150);for(let x=X0();x<=X0()+VW()+20;x+=20)c.lineTo(x,146+Math.sin(x*.04+t*2.4)*7);c.lineTo(X0()+VW(),178);c.lineTo(X0(),178);c.closePath();c.fill();
  c.fillStyle="#e6c784";for(let i=0;i<70;i++){c.beginPath();c.arc(X0()+(i*97)%VW(),190+((i*53)%(VH()+Y0()-200)),2.5,0,7);c.fill();}
  // starfish and a towel at the edges
  c.fillStyle="#ff8a5c";[[X0()+60,MH-40],[X0()+VW()-70,MH-20]].forEach(([x,y])=>{c.save();c.translate(x,y);c.beginPath();for(let k=0;k<10;k++){const r=k%2?7:18,a=k*Math.PI/5-Math.PI/2;c.lineTo(Math.cos(a)*r,Math.sin(a)*r);}c.fill();c.restore();});
  for(const [x,y] of HOLES){c.fillStyle="#d9b56c";c.beginPath();c.ellipse(x,y+18,56,19,0,0,7);c.fill();c.fillStyle="#a8823f";c.beginPath();c.ellipse(x,y+18,44,12,0,0,7);c.fill();}
  palmLeaves(c,X0()-10,Y0()+10,1,t);palmLeaves(c,X0()+VW()+10,Y0()+10,-1,t);
}
function drawShellThing(c,p,s){c.save();c.translate(p.x,p.y);c.scale(s,s);
  if(p.k==="crab"){c.fillStyle="#ff4545";c.strokeStyle="#c21f1f";c.lineWidth=4;
    for(const sx of[-1,1]){c.beginPath();c.arc(sx*36,-18,13,0,7);c.fill();c.fillStyle="#c21f1f";c.beginPath();c.moveTo(sx*36,-18);c.lineTo(sx*48,-26);c.lineTo(sx*44,-12);c.fill();c.fillStyle="#ff4545";
      for(let k=0;k<3;k++){c.beginPath();c.moveTo(sx*18,4+k*6);c.lineTo(sx*36,12+k*7);c.stroke();}}
    c.beginPath();c.ellipse(0,0,30,22,0,0,7);c.fill();
    for(const sx of[-1,1]){c.strokeStyle="#c21f1f";c.beginPath();c.moveTo(sx*8,-18);c.lineTo(sx*10,-30);c.stroke();c.fillStyle="#fff";c.beginPath();c.arc(sx*10,-32,7,0,7);c.fill();c.fillStyle="#111";c.beginPath();c.arc(sx*10,-32,3.5,0,7);c.fill();}
    c.strokeStyle="#7a1010";c.lineWidth=3;c.beginPath();c.arc(0,2,8,.2,Math.PI-.2);c.stroke();}
  else if(p.k==="pearl"){c.fillStyle="#9a8fb3";c.beginPath();c.ellipse(0,8,36,16,0,0,7);c.fill();c.fillStyle="#c9bfe0";c.beginPath();c.ellipse(0,-14,34,20,0,Math.PI,0);c.fill();
    const g=c.createRadialGradient(-4,-4,1,0,0,13);g.addColorStop(0,"#ffffff");g.addColorStop(1,"#d6e4ff");c.fillStyle=g;c.beginPath();c.arc(0,0,13,0,7);c.fill();}
  else{c.fillStyle="#ff9eb8";c.beginPath();c.moveTo(0,20);for(let i=0;i<=8;i++){const a=Math.PI+i*Math.PI/8;c.lineTo(Math.cos(a)*34,-4+Math.sin(a)*32);}c.closePath();c.fill();
    c.strokeStyle="#e5708f";c.lineWidth=3;for(let i=1;i<8;i++){const a=Math.PI+i*Math.PI/8;c.beginPath();c.moveTo(0,18);c.lineTo(Math.cos(a)*30,-4+Math.sin(a)*28);c.stroke();}
    c.fillStyle="#ffc4d4";rr2(c,-10,14,20,10,4);c.fill();}
  c.restore();}
function shellTick(dt,t){const c=mg2d;
  const S=MG.info.items;while(MG.next<S.length&&S[MG.next].t<=t){const s=S[MG.next++],hole=HOLES[s.h]||HOLES[0];MG.pops.push({id:s.i,x:hole[0],y:hole[1],k:s.k,t:t-s.t,life:s.life});burst(hole[0],hole[1]+16,"#e6c784",7,120,400,4);}
  for(let i=MG.pops.length-1;i>=0;i--){const p=MG.pops[i];p.t+=dt;if(p.t>p.life)MG.pops.splice(i,1);}
  const sh=MG.shake>0?(MG.shake-=dt,Math.sin(t*90)*8):0;
  c.save();c.translate(sh,0);shellScene(t);
  for(const p of MG.pops){const s=p.t<.15?p.t/.15:p.t>p.life-.15?(p.life-p.t)/.15:1;drawShellThing(c,{...p,y:p.y+(1-s)*20},Math.max(.01,s));}c.restore();
}
function shellTap(x,y){let best=null,bd=60;for(const p of MG.pops){const d=Math.hypot(p.x-x,p.y-y);if(d<bd){bd=d;best=p;}}
  if(!best)return;MG.pops.splice(MG.pops.indexOf(best),1);MG.caught.push(best.id);addScore(best.k==="crab"?-2:best.k==="pearl"?3:1,best.x,best.y-30);}

/* ---------- TREASURE DIG (a desert island) ---------- */
const DCOLS=7,DROWS=5,DX=24,DY=92,DW=(MW-48)/7,DH=(MH-110)/5;
function digInit(){Object.assign(MG,{caught:[],cells:Array(DCOLS*DROWS).fill(null),shovels:MG.info.shovels,busy:false});$mg("mgTime").textContent=MG.shovels;}
function digScene(t=0,demoCells){const c=mg2d;
  skyFill(c,"#7fd0ff","#ffe7b8",70);sun(c,X0()+90,Y0()+50,30,t);clouds(c,t,6,0,4);
  c.fillStyle="#2fa8e8";c.fillRect(X0(),40,VW(),40);c.strokeStyle="rgba(255,255,255,.55)";c.lineWidth=2;for(let k=0;k<3;k++){c.beginPath();for(let x=X0();x<=X0()+VW();x+=16)c.lineTo(x,48+k*10+Math.sin(x*.05+t*2+k)*2);c.stroke();}
  const g=c.createLinearGradient(0,70,0,MH);g.addColorStop(0,"#ffd9a0");g.addColorStop(1,"#efb262");c.fillStyle=g;c.fillRect(X0(),70,VW(),VH()+Y0()-70);
  palmLeaves(c,X0()+VW()-30,Y0()+20,-1,t);
  // the dig board: a wooden frame on the sand
  c.fillStyle="#a8642a";rr2(c,DX-12,DY-12,DCOLS*DW+24,DROWS*DH+24,18);c.fill();c.fillStyle="#c97d38";rr2(c,DX-6,DY-6,DCOLS*DW+12,DROWS*DH+12,14);c.fill();
  c.font='30px "HeeboDisplay","Lilita One", sans-serif';c.textAlign="center";c.lineWidth=7;c.strokeStyle="#7a4a12";c.strokeText("Find the 2 treasure chests!",MW/2,62);c.fillStyle="#fff";c.fillText("Find the 2 treasure chests!",MW/2,62);
  const cells=demoCells||(MG&&MG.cells);for(let i=0;i<DCOLS*DROWS;i++)drawCell(i,cells,t);}
function drawDigItem(c,item,cx,cy,s=1){c.save();c.translate(cx,cy);c.scale(s,s);
  if(item==="chest"){c.fillStyle="#a8642a";rr2(c,-26,-14,52,30,6);c.fill();c.fillStyle="#c97d38";rr2(c,-26,-24,52,14,7);c.fill();
    c.fillStyle="#ffd23a";c.fillRect(-28,-12,56,5);c.fillRect(-4,-14,8,14);c.beginPath();c.arc(0,-24,10,Math.PI,0);c.fill();}
  else if(item==="gem"){c.fillStyle="#2fd3ff";c.beginPath();c.moveTo(0,-22);c.lineTo(18,-6);c.lineTo(0,12);c.lineTo(-18,-6);c.closePath();c.fill();c.fillStyle="rgba(255,255,255,.6)";c.beginPath();c.moveTo(0,-22);c.lineTo(6,-6);c.lineTo(-6,-6);c.fill();}
  else if(item==="coins"){for(const [a,b] of[[-10,4],[8,4],[0,-6]]){c.fillStyle="#c98a00";c.beginPath();c.arc(a,b+2,11,0,7);c.fill();c.fillStyle="#ffd23a";c.beginPath();c.arc(a,b,11,0,7);c.fill();}}
  c.restore();}
function drawCell(i,cells,t){const c=mg2d,x=DX+(i%DCOLS)*DW,y=DY+Math.floor(i/DCOLS)*DH,cell=cells?cells[i]:null;
  if(!cell){const g=c.createLinearGradient(0,y,0,y+DH);g.addColorStop(0,"#ffe3a8");g.addColorStop(1,"#efc27a");c.fillStyle=g;rr2(c,x+4,y+4,DW-8,DH-8,12);c.fill();
    c.fillStyle="rgba(255,255,255,.45)";rr2(c,x+10,y+8,DW-20,6,3);c.fill();
    c.fillStyle="#e2ae62";for(const [a,b,r] of[[.3,.45,3],[.7,.65,2.5],[.5,.8,2]]){c.beginPath();c.arc(x+DW*a,y+DH*b,r,0,7);c.fill();}return;}
  const cx=x+DW/2,cy=y+DH/2;c.fillStyle="#b07a40";rr2(c,x+4,y+4,DW-8,DH-8,12);c.fill();
  if(cell==="busy"){c.fillStyle="#7a4a1a";c.beginPath();c.ellipse(cx,cy+6,24+Math.sin(t*20)*3,10,0,0,7);c.fill();return;}
  c.fillStyle="#6b4520";c.beginPath();c.ellipse(cx,cy+10,30,12,0,0,7);c.fill();
  if(cell.item){if(cell.item==="chest"){c.save();c.globalAlpha=.35+.25*Math.sin(t*4);c.fillStyle="#ffe27a";c.beginPath();c.arc(cx,cy,34,0,7);c.fill();c.restore();}drawDigItem(c,cell.item,cx,cy);}
  else{const h=cell.hint,col=h<=1?"#ff4545":h===2?"#ff8a1c":h===3?"#e8b400":"#4f9bff";
    c.font='34px "HeeboDisplay","Lilita One", sans-serif';c.textAlign="center";c.textBaseline="middle";c.lineWidth=7;c.strokeStyle="#5a3410";c.strokeText(h,cx,cy-2);c.fillStyle=col;c.fillText(h,cx,cy-2);c.textBaseline="alphabetic";}
}
function digTick(dt,t){digScene(t);}
async function digTap(x,y){
  if(MG.busy||MG.shovels<=0)return;const col=Math.floor((x-DX)/DW),row=Math.floor((y-DY)/DH);
  if(col<0||col>=DCOLS||row<0||row>=DROWS)return;const i=row*DCOLS+col;if(MG.cells[i])return;
  const round=MG;round.busy=true;round.cells[i]="busy";sfx.paddle();const cx0=DX+col*DW+DW/2,cy0=DY+row*DH+DH/2;burst(cx0,cy0,"#e2ae62",14,200,500,5);
  const r=await api("/api/minigame/dig",{id:round.id,cell:i});
  if(MG!==round||round.state!=="play")return;round.busy=false;
  if(!r.ok){round.cells[i]=null;toast(r.data.error||"Couldn't dig there.");return;}
  const d=r.data;round.cells[i]={item:d.item,hint:d.hint};round.shovels=d.shovels;$mg("mgTime").textContent=d.shovels;
  if(d.value){round.score=d.score;$mg("mgScore").textContent=d.score;bumpHud();round.fx.push({x:cx0,y:cy0-20,text:"+"+d.value,col:"#ffffff",t:0});
    burst(cx0,cy0-10,"#ffd23a",d.item==="chest"?26:12,240,300,6);if(d.item==="chest"){round.flash=.35;sfx.success();}else sfx.tick(true);}
  if(d.shovels<=0||d.allChests){round.busy=true;setTimeout(()=>{if(MG===round)endRound();},1100);}
}

/* ---------- JUMPI FLAP (the beach, Flappy-style) ---------- */
const FL={grav:1500,up:-440,r:22,ground:MH-46};
function flapInit(){const f=MG.info.flap;Object.assign(MG,{fy:MH*.42,fv:0,fang:0,flapT:-9,scroll:0,crashed:false,crashT:0,passed:0,caught:[],next:0,fl:f});flapUp();}
function flapUp(){if(!MG||MG.state!=="play"||MG.crashed)return;MG.fv=FL.up;MG.flapT=performance.now()/1000;sfx.hop();burst(MG.fl.jumpiX-18,MG.fy+18,"#ffffff",4,80,200,3);}
// the beach, scrolling at different speeds
function beachScene(c,scroll,t){
  skyFill(c,"#46b6ff","#ffe1a6",FL.ground-40);sun(c,MW-140,Y0()+70,40,t);
  for(let i=0;i<7;i++){const span=VW()+320,x=X0()-160+(((i*290-scroll*.08)%span)+span)%span;cloud(c,x,Y0()+30+(i*53)%110,.6+(i%3)*.25);}
  // far islands and the sea
  const sy=FL.ground-110;c.fillStyle="#7fc9a0";for(let k=0;k<3;k++){const x=X0()+(((k*420-scroll*.15)%(VW()+500))+VW()+500)%(VW()+500)-200;c.beginPath();c.ellipse(x,sy,120,26,0,Math.PI,0);c.fill();}
  const g=c.createLinearGradient(0,sy,0,FL.ground);g.addColorStop(0,"#1f9be8");g.addColorStop(1,"#5fdcff");c.fillStyle=g;c.fillRect(X0(),sy,VW(),FL.ground-sy);
  c.strokeStyle="rgba(255,255,255,.55)";c.lineWidth=2;for(let k=0;k<4;k++){c.beginPath();for(let x=X0();x<=X0()+VW();x+=16)c.lineTo(x,sy+12+k*16+Math.sin((x+scroll*.3)*.04+t*2+k)*2.5);c.stroke();}
  // sand, with shells and umbrellas going by
  c.fillStyle="#ffe0a0";c.fillRect(X0(),FL.ground-6,VW(),VH()+Y0()-FL.ground+6);
  c.fillStyle="rgba(255,255,255,.85)";c.beginPath();c.moveTo(X0(),FL.ground-4);for(let x=X0();x<=X0()+VW()+16;x+=16)c.lineTo(x,FL.ground-8+Math.sin((x+scroll)*.05+t*3)*3);c.lineTo(X0()+VW(),FL.ground+4);c.lineTo(X0(),FL.ground+4);c.closePath();c.fill();
  c.fillStyle="#f0c878";const off=scroll%40;for(let x=X0()-off;x<X0()+VW()+40;x+=40){c.beginPath();c.arc(x,FL.ground+16+(Math.abs(Math.round((x+scroll)/40))%3)*8,3,0,7);c.fill();}
  const cols=["#ff4f6d","#2fb6ff","#ffcf33","#9b5cff"];
  for(let k=-1;k<6;k++){const span=360,base=Math.floor(scroll*.6/span),n=base+k,x=X0()+n*span-scroll*.6+120;if(x<X0()-120||x>X0()+VW()+120)continue;
    c.strokeStyle="#f4f1ea";c.lineWidth=4;c.beginPath();c.moveTo(x,FL.ground+20);c.lineTo(x-6,FL.ground-50);c.stroke();
    c.fillStyle=cols[Math.abs(n)%4];c.beginPath();c.moveTo(x-6-46,FL.ground-44);c.quadraticCurveTo(x-6,FL.ground-86,x-6+46,FL.ground-44);c.closePath();c.fill();
    c.fillStyle="rgba(255,255,255,.8)";c.beginPath();c.moveTo(x-6-15,FL.ground-50);c.quadraticCurveTo(x-6,FL.ground-84,x-6+15,FL.ground-50);c.closePath();c.fill();}
}
// a surfboard standing up from the sand (up=false) or hanging from the top (up=true); x = left edge
function drawBoard(c,x,yEdge,w,col,up,lim){const top=lim?lim[0]:Y0()-20,bot=lim?lim[1]:VH()+Y0()+20,len=up?yEdge-top:bot-yEdge;c.save();
  const y=up?top:yEdge;c.fillStyle="rgba(0,0,0,.15)";rr2(c,x+6,y+(up?0:6),w,len,w/2);c.fill();
  const g=c.createLinearGradient(x,0,x+w,0);g.addColorStop(0,col);g.addColorStop(.5,new THREE.Color(col).lerp(new THREE.Color("#ffffff"),.35).getStyle());g.addColorStop(1,col);
  c.fillStyle=g;rr2(c,x,y,w,len,w/2);c.fill();
  c.fillStyle="#ffffff";rr2(c,x+w/2-4,y+(up?0:22),8,len-22,4);c.fill();
  c.fillStyle=new THREE.Color(col).multiplyScalar(.75).getStyle();const tipY=up?yEdge-34:yEdge+12;rr2(c,x+8,tipY,w-16,22,10);c.fill();
  c.strokeStyle="rgba(0,0,0,.18)";c.lineWidth=3;rr2(c,x,y,w,len,w/2);c.stroke();c.restore();}
function drawGoldShell(c,x,y,s,t){c.save();c.translate(x,y+Math.sin(t*4+x)*3);c.scale(s,s);
  c.fillStyle="rgba(255,230,120,.35)";c.beginPath();c.arc(0,0,26+Math.sin(t*6)*3,0,7);c.fill();
  c.fillStyle="#ffc21a";c.beginPath();c.moveTo(0,14);for(let i=0;i<=8;i++){const a=Math.PI+i*Math.PI/8;c.lineTo(Math.cos(a)*20,-2+Math.sin(a)*19);}c.closePath();c.fill();
  c.strokeStyle="#c98a00";c.lineWidth=2;for(let i=1;i<8;i++){const a=Math.PI+i*Math.PI/8;c.beginPath();c.moveTo(0,12);c.lineTo(Math.cos(a)*17,-2+Math.sin(a)*16);c.stroke();}
  c.fillStyle="#fff3b0";c.beginPath();c.ellipse(-6,-8,4,6,.5,0,7);c.fill();c.restore();}
// Jumpi with a swim ring, flapping its little arms
function drawFlapJumpi(c,x,y,s,ang,flap,dizzy){c.save();c.translate(x,y);c.scale(s,s);c.rotate(ang);const col=skinHex();
  [-1,1].forEach(sx=>{c.save();c.translate(sx*20,4);c.rotate(sx*(flap?-1.1:-.2));c.fillStyle=col;c.beginPath();c.ellipse(sx*8,0,11,6,0,0,7);c.fill();c.restore();});
  c.fillStyle=col;c.beginPath();c.ellipse(0,-4,24,22,0,0,7);c.fill();
  c.fillStyle="rgba(255,255,255,.28)";c.beginPath();c.ellipse(-9,-15,8,5,-.5,0,7);c.fill();
  // swim ring
  c.lineWidth=7;["#ff4f6d","#ffffff"].forEach((sc,k)=>{c.strokeStyle=sc;for(let i=0;i<4;i++){c.beginPath();c.ellipse(0,12,22,7,0,Math.PI*(i/2)+k*Math.PI/4,Math.PI*(i/2)+k*Math.PI/4+Math.PI/4);c.stroke();}});
  [-1,1].forEach(sx=>{c.fillStyle="#fff";c.beginPath();c.ellipse(8+sx*8,-8,7,8,0,0,7);c.fill();
    if(dizzy){c.strokeStyle="#1d2b4f";c.lineWidth=2.5;c.beginPath();c.moveTo(8+sx*8-4,-12);c.lineTo(8+sx*8+4,-4);c.moveTo(8+sx*8+4,-12);c.lineTo(8+sx*8-4,-4);c.stroke();}
    else{c.fillStyle="#1d2b4f";c.beginPath();c.arc(10+sx*8,-7,4,0,7);c.fill();c.fillStyle="#fff";c.beginPath();c.arc(11+sx*8,-9,1.5,0,7);c.fill();}});
  c.strokeStyle="rgba(0,0,0,.45)";c.lineWidth=2.5;c.lineCap="round";c.beginPath();dizzy?c.arc(10,6,4,Math.PI+.3,-.3):c.arc(10,1,5,.2,Math.PI-.2);c.stroke();c.restore();}
const boardCol=k=>["#ff5fa8","#1fb6ff","#2fd36b","#ffb21f","#9b5cff"][k%5];
function flapTick(dt,t){const c=mg2d,f=MG.fl,items=MG.info.items;
  if(!MG.crashed){MG.scroll=t*f.speed;}
  MG.fv+=FL.grav*dt;MG.fy+=MG.fv*dt;
  if(MG.fy<FL.r){MG.fy=FL.r;MG.fv=Math.max(0,MG.fv);}
  MG.fang+=((MG.crashed?1.6:Math.max(-.5,Math.min(1.2,MG.fv/700)))-MG.fang)*Math.min(1,dt*8);
  const jx=f.jumpiX,sh=MG.shake>0?(MG.shake-=dt,Math.sin(t*90)*8):0;
  c.save();c.translate(sh,0);beachScene(c,MG.scroll,t);
  // the boards on screen
  const first=Math.max(0,Math.floor((MG.scroll-f.first+X0()-120)/f.gap)),last=Math.min(items.length-1,Math.ceil((MG.scroll-f.first+X0()+VW()+120)/f.gap));
  for(let k=first;k<=last;k++){const it=items[k],x=f.first+k*f.gap-MG.scroll,top=it.y-it.size/2,bot=it.y+it.size/2;
    drawBoard(c,x-f.half,top,f.half*2,boardCol(k),true);drawBoard(c,x-f.half,bot,f.half*2,boardCol(k+2),false);
    if(it.shell&&!MG.caught.includes(k))drawGoldShell(c,x,it.y,1,t);
    if(!MG.crashed){
      // passing: score once
      if(k>=MG.passed&&x+f.half<jx-FL.r){MG.passed=k+1;addScore(1,jx,MG.fy-40);}
      // golden shell
      if(it.shell&&!MG.caught.includes(k)&&Math.hypot(x-jx,it.y-MG.fy)<FL.r+18){MG.caught.push(k);addScore(2,x,it.y-30);}
      // hitting a board
      if(Math.abs(x-jx)<f.half+FL.r-6&&(MG.fy-FL.r+6<top||MG.fy+FL.r-6>bot))flapCrash(t);}}
  if(!MG.crashed&&MG.fy+FL.r>FL.ground)flapCrash(t);
  if(MG.fy+FL.r>FL.ground){MG.fy=FL.ground-FL.r;MG.fv=0;}
  const flapping=performance.now()/1000-MG.flapT<.18;
  drawFlapJumpi(c,jx,MG.fy,1.15,MG.fang,flapping,MG.crashed);
  c.restore();
  if(MG.crashed&&t-MG.crashT>1.1&&MG.state==="play")endRound();
}
function flapCrash(t){MG.crashed=true;MG.crashT=t;MG.shake=.4;MG.flash=.4;MG.fv=Math.min(MG.fv,-200);sfx.error();burst(MG.fl.jumpiX,MG.fy,"#ffe0a0",18,240,500,6);burst(MG.fl.jumpiX,MG.fy,"#ffffff",8,200,300,5);}


/* =====================================================================
   THE FUTURE CITY GAMES (the stands next to Neon Square; the server scripts every round: routes/rewards.js)
   DRONE RACE: fly Jumpi's drone through the rings, dodge the storm clouds (5 lanes)
   ROBO FIX:   robots roll along the belt; give each one the part it needs (bolt, battery, chip)
   ROOF HOP:   run over the rooftops of the city and jump the gaps
   ===================================================================== */
const D_LANES=[136,248,360,472,584],D_Y=392,D_TOP=-30;
const neonStroke=(c,col,w,blur=14)=>{c.strokeStyle=col;c.lineWidth=w;c.shadowColor=col;c.shadowBlur=blur;};
// a night city seen from above, scrolling down
function droneScene(c,scroll,t){
  skyFill(c,"#0b0f2e","#1a1250");
  // buildings on both sides (tops seen from above, with glowing windows)
  for(let side=0;side<2;side++)for(let k=-1;k<8;k++){const h=110,y=((k*h+scroll*.9)%(h*8)+h*8)%(h*8)-h,x=side?MW+20:X0()-40,w=side?X0()+VW()-MW+20:Math.max(0,-X0()+70);
    if(w<=0)continue;c.fillStyle=["#1d2547","#24204f","#1a2b4f"][(k+side)&3%3];c.fillRect(x,y,w,h-12);
    c.fillStyle="rgba(255,214,120,.55)";for(let r=0;r<3;r++)for(let q=0;q<Math.max(1,Math.floor(w/22));q++)if(((k*7+r*3+q)&3)!==0)c.fillRect(x+6+q*22,y+10+r*30,12,14);}
  // the hover road: dark glass with glowing lane lines
  const L=96,R=MW-96;c.fillStyle="#141a3d";c.fillRect(L-20,Y0(),R-L+40,VH());
  for(let i=0;i<=D_LANES.length;i++){const x=L+i*(R-L)/D_LANES.length;c.save();neonStroke(c,i%2?"#ff4fd8":"#59e0ff",3,10);c.setLineDash([26,22]);c.lineDashOffset=-scroll;c.beginPath();c.moveTo(x,Y0());c.lineTo(x,Y0()+VH());c.stroke();c.restore();}
  // little cars far below, going the other way
  for(let k=0;k<5;k++){const y=((k*173-scroll*.5)%(VH()+200)+VH()+200)%(VH()+200)+Y0()-100,x=L+30+((k*131)%(R-L-60));c.fillStyle="rgba(255,255,255,.12)";c.beginPath();c.ellipse(x,y,9,16,0,0,7);c.fill();}}
function drawRing(c,x,y,gold,t,s=1){c.save();c.translate(x,y);c.scale(s,s);const col=gold?"#ffd23a":"#59e0ff";
  c.save();neonStroke(c,col,9,20);c.beginPath();c.ellipse(0,0,38,16,0,0,7);c.stroke();c.restore();
  c.strokeStyle="#ffffff";c.lineWidth=3;c.beginPath();c.ellipse(0,0,38,16,0,Math.PI*1.1,Math.PI*1.6);c.stroke();
  if(gold){c.fillStyle="#fff6c0";for(let k=0;k<3;k++){const a=t*3+k*2.1;c.beginPath();c.arc(Math.cos(a)*44,Math.sin(a)*20,3,0,7);c.fill();}}c.restore();}
function drawStorm(c,x,y,t,s=1){c.save();c.translate(x,y);c.scale(s,s);c.fillStyle="#3b3f63";c.beginPath();c.arc(-18,0,18,0,7);c.arc(4,-8,22,0,7);c.arc(24,2,16,0,7);c.arc(2,8,18,0,7);c.fill();
  c.fillStyle="#4c517a";c.beginPath();c.arc(-6,-10,10,0,7);c.fill();
  if(Math.sin(t*9+x)>.2){c.fillStyle="#ffe14d";c.beginPath();c.moveTo(2,10);c.lineTo(-8,30);c.lineTo(0,28);c.lineTo(-6,46);c.lineTo(10,22);c.lineTo(2,24);c.lineTo(8,10);c.closePath();c.fill();}c.restore();}
// Jumpi riding a little drone
function drawDrone(c,x,y,t,tilt=0,s=1){c.save();c.translate(x,y);c.rotate(tilt*.35);c.scale(s,s);
  c.fillStyle="rgba(89,224,255,.18)";c.beginPath();c.ellipse(0,26,60,14,0,0,7);c.fill();
  [[-44,-6],[44,-6],[-34,20],[34,20]].forEach(([px,py],k)=>{c.strokeStyle="#c9d2e3";c.lineWidth=5;c.beginPath();c.moveTo(0,8);c.lineTo(px,py);c.stroke();
    c.fillStyle="rgba(220,240,255,.55)";c.beginPath();c.ellipse(px,py,22,6+Math.abs(Math.sin(t*40+k))*3,0,0,7);c.fill();c.fillStyle="#2a3042";c.beginPath();c.arc(px,py,5,0,7);c.fill();});
  c.fillStyle="#e9eef7";c.beginPath();c.ellipse(0,10,30,14,0,0,7);c.fill();c.fillStyle="#59e0ff";c.fillRect(-20,14,40,4);
  drawMiniJumpi(c,0,6,.62,skinHex(),tilt);c.restore();}
function droneInit(){Object.assign(MG,{lane:2,dx:D_LANES[2],tilt:0,items:[],next:0,caught:[],drag:false});}
function droneMove(d){if(!MG||MG.state!=="play")return;MG.lane=Math.max(0,Math.min(4,MG.lane+d));sfx.tick(true);}
function droneTick(dt,t){const c=mg2d,items=MG.info.items;
  if(MG.keys.ArrowLeft||MG.keys.KeyA){MG.keys.ArrowLeft=MG.keys.KeyA=false;droneMove(-1);}
  if(MG.keys.ArrowRight||MG.keys.KeyD){MG.keys.ArrowRight=MG.keys.KeyD=false;droneMove(1);}
  const want=D_LANES[MG.lane],ox=MG.dx;MG.dx+=(want-MG.dx)*Math.min(1,dt*12);MG.tilt+=(((MG.dx-ox)/Math.max(dt,.001))*.004-MG.tilt)*Math.min(1,dt*10);
  const sh=MG.shake>0?(MG.shake-=dt,Math.sin(t*90)*7):0;c.save();c.translate(sh,0);
  droneScene(c,t*260,t);
  while(MG.next<items.length&&items[MG.next].t<=t){MG.items.push({...items[MG.next],y:D_TOP});MG.next++;}
  for(let i=MG.items.length-1;i>=0;i--){const it=MG.items[i];it.y=D_TOP+(t-it.t)*it.v;const x=D_LANES[it.lane];
    if(!it.done&&it.y>D_Y-24&&it.y<D_Y+24&&Math.abs(x-MG.dx)<46){it.done=true;MG.caught.push(it.i);
      if(it.k==="storm"){addScore(-2,x,D_Y-50);MG.flash=.25;}else{addScore(it.k==="gold"?3:1,x,D_Y-50);burst(x,D_Y,it.k==="gold"?"#ffd23a":"#59e0ff",12);}}
    if(it.y>MH+60||it.done&&it.k!=="storm"){MG.items.splice(i,1);continue;}
    if(it.k==="storm")drawStorm(c,x,it.y,t,1.05);else drawRing(c,x,it.y,it.k==="gold",t,1+(it.y/MH)*.15);}
  drawDrone(c,MG.dx,D_Y+Math.sin(t*5)*3,t,MG.tilt);c.restore();}
function droneTap(x){if(!MG||MG.state!=="play")return;let best=0,bd=1e9;D_LANES.forEach((lx,i)=>{const d=Math.abs(lx-x);if(d<bd){bd=d;best=i;}});if(best!==MG.lane){MG.lane=best;sfx.tick(true);}}

/* ---------- ROBO FIX ---------- */
const R_BELT=278,R_ZONE=[260,460],R_PARTS=[{k:"bolt",col:"#c9d2e3",key:"1"},{k:"battery",col:"#ffd65a",key:"2"},{k:"chip",col:"#59e0ff",key:"3"}],R_BTN=[[200,428],[360,428],[520,428]];
function drawPart(c,k,x,y,s=1){c.save();c.translate(x,y);c.scale(s,s);
  if(k==="bolt"){c.fillStyle="#c9d2e3";c.beginPath();for(let i=0;i<6;i++){const a=i/6*Math.PI*2;c.lineTo(Math.cos(a)*16,-14+Math.sin(a)*8);}c.fill();c.fillStyle="#8e98aa";c.fillRect(-6,-10,12,30);c.strokeStyle="#6b7590";c.lineWidth=2;for(let yy=-4;yy<18;yy+=6){c.beginPath();c.moveTo(-6,yy);c.lineTo(6,yy+3);c.stroke();}}
  else if(k==="battery"){c.fillStyle="#2a3042";c.beginPath();c.roundRect(-12,-18,24,38,5);c.fill();c.fillStyle="#ffd65a";c.beginPath();c.roundRect(-9,-4,18,21,3);c.fill();c.fillStyle="#c9d2e3";c.fillRect(-5,-23,10,6);
    c.fillStyle="#2a3042";c.beginPath();c.moveTo(2,-1);c.lineTo(-4,8);c.lineTo(1,8);c.lineTo(-2,15);c.lineTo(5,5);c.lineTo(0,5);c.closePath();c.fill();}
  else{c.fillStyle="#1d2433";c.beginPath();c.roundRect(-18,-16,36,32,4);c.fill();c.fillStyle="#59e0ff";c.fillRect(-9,-8,18,16);c.fillStyle="#c9d2e3";for(let i=-2;i<=2;i++){c.fillRect(i*7-1.5,-21,3,6);c.fillRect(i*7-1.5,15,3,6);}}
  c.restore();}
function drawRobot(c,x,y,r,t){const happy=r.fixed||r.k==="ok",sad=r.failed;c.save();c.translate(x,y);
  const body=r.k==="gold"?"#ffd23a":"#e9eef7",dark=r.k==="gold"?"#c98a00":"#9aa6c2";
  c.fillStyle="rgba(0,0,0,.2)";c.beginPath();c.ellipse(0,40,34,8,0,0,7);c.fill();
  c.fillStyle=dark;c.beginPath();c.arc(-18,34,9,0,7);c.arc(18,34,9,0,7);c.fill();
  c.fillStyle=body;c.beginPath();c.roundRect(-30,-24,60,56,14);c.fill();c.fillStyle=dark;c.fillRect(-18,4,36,4);
  c.fillStyle=body;c.beginPath();c.roundRect(-24,-62,48,36,12);c.fill();c.fillStyle=dark;c.fillRect(-2,-76,4,14);
  c.fillStyle=r.fixed?"#7dff9b":r.k==="ok"?"#7dff9b":"#ff6b5b";c.beginPath();c.arc(0,-78,5+(happy?0:Math.abs(Math.sin(t*8))*2),0,7);c.fill();
  c.fillStyle="#1d2433";c.beginPath();c.roundRect(-18,-56,36,22,8);c.fill();c.fillStyle=happy?"#7dff9b":sad?"#ff6b5b":"#59e0ff";
  if(happy){c.beginPath();c.arc(-8,-45,4,0,7);c.arc(8,-45,4,0,7);c.fill();c.strokeStyle="#7dff9b";c.lineWidth=2.5;c.beginPath();c.arc(0,-43,7,.3,Math.PI-.3);c.stroke();}
  else{c.fillRect(-12,-48,8,4);c.fillRect(4,-48,8,4);}
  if(!r.fixed&&r.k!=="ok"&&!r.failed){c.fillStyle="#fff";c.beginPath();c.roundRect(14,-118,52,44,12);c.fill();c.beginPath();c.moveTo(22,-76);c.lineTo(16,-66);c.lineTo(32,-76);c.fill();drawPart(c,R_PARTS[r.need].k,40,-95,.7);}
  if(r.fixed){c.fillStyle="#fff6a8";for(let k=0;k<4;k++){const a=t*4+k*1.6;c.beginPath();c.arc(Math.cos(a)*36,-30+Math.sin(a)*30,3,0,7);c.fill();}}
  c.restore();}
function robotScene(c,t,scroll){skyFill(c,"#1a1f45","#2d2a6b");
  // the factory: big windows to the night city, pipes, the scanner zone
  c.fillStyle="#232a52";c.fillRect(X0(),Y0(),VW(),210-Y0());for(let k=0;k<6;k++){const x=X0()+40+k*((VW()-80)/6);c.fillStyle="#141a3d";c.fillRect(x,40,(VW()-80)/6-24,120);c.fillStyle="rgba(89,224,255,.35)";for(let q=0;q<4;q++)c.fillRect(x+10+q*24,60+(q%2)*30,14,40+(q*13)%30);}
  c.fillStyle="#3a4470";c.fillRect(X0(),206,VW(),10);
  c.fillStyle="#2a3155";c.fillRect(X0(),R_BELT+42,VW(),40);c.fillStyle="#1d2340";for(let x=X0()-((scroll)%40);x<X0()+VW();x+=40)c.fillRect(x,R_BELT+44,20,36);
  c.fillStyle="#46516a";c.fillRect(X0(),R_BELT+36,VW(),8);
  const zg=c.createLinearGradient(0,150,0,R_BELT+42);zg.addColorStop(0,"rgba(125,255,155,0)");zg.addColorStop(1,"rgba(125,255,155,.22)");c.fillStyle=zg;c.fillRect(R_ZONE[0],150,R_ZONE[1]-R_ZONE[0],R_BELT+42-150);
  c.save();neonStroke(c,"#7dff9b",3,12);c.setLineDash([10,8]);c.strokeRect(R_ZONE[0],150,R_ZONE[1]-R_ZONE[0],R_BELT+42-150);c.restore();
  c.fillStyle="#7dff9b";c.font='20px "HeeboDisplay","Lilita One", sans-serif';c.textAlign="center";c.fillText(I18N.T("REPAIR ZONE"),(R_ZONE[0]+R_ZONE[1])/2,142);}
function drawPartButtons(c,t,press){R_PARTS.forEach((p,i)=>{const [x,y]=R_BTN[i],down=press&&press.i===i&&t-press.t<.15;c.save();c.translate(x,y+(down?4:0));
  c.fillStyle="rgba(0,0,0,.3)";c.beginPath();c.roundRect(-58,-30+(down?0:6),116,64,18);c.fill();c.fillStyle="#fff";c.beginPath();c.roundRect(-58,-34,116,64,18);c.fill();
  c.strokeStyle=p.col;c.lineWidth=4;c.stroke();drawPart(c,p.k,-22,-2,.9);c.fillStyle="#24305e";c.font='26px "HeeboDisplay","Lilita One", sans-serif';c.textAlign="center";c.textBaseline="middle";c.fillText(p.key,30,-2);c.restore();});}
function robotInit(){Object.assign(MG,{bots:[],next:0,caught:[],press:null});}
const robotX=(r,t)=>-60+(t-r.t)*r.v;
function robotTick(dt,t){const c=mg2d,items=MG.info.items,sh=MG.shake>0?(MG.shake-=dt,Math.sin(t*90)*7):0;c.save();c.translate(sh,0);
  robotScene(c,t,t*150);
  while(MG.next<items.length&&items[MG.next].t<=t){MG.bots.push({...items[MG.next]});MG.next++;}
  for(let i=MG.bots.length-1;i>=0;i--){const r=MG.bots[i],x=robotX(r,t);if(x>MW+80){MG.bots.splice(i,1);continue;}drawRobot(c,x,R_BELT,r,t);}
  drawPartButtons(c,t,MG.press);c.restore();}
function robotFix(i){if(!MG||MG.state!=="play")return;const t=(performance.now()-MG.t0)/1000;MG.press={i,t};
  const inZone=MG.bots.filter(r=>!r.fixed&&!r.failed&&(()=>{const x=robotX(r,t);return x>R_ZONE[0]&&x<R_ZONE[1];})());
  if(!inZone.length){sfx.tick(true);return;}
  const r=inZone.reduce((a,b)=>Math.abs(robotX(a,t)-360)<Math.abs(robotX(b,t)-360)?a:b),x=robotX(r,t);
  if(r.k==="ok"){r.failed=true;MG.caught.push(r.i);addScore(-1,x,R_BELT-120);return;}   // it didn't need anything!
  if(r.need===i){r.fixed=true;MG.caught.push(r.i);addScore(r.k==="gold"?3:1,x,R_BELT-120);burst(x,R_BELT-40,r.k==="gold"?"#ffd23a":"#7dff9b",12);}
  else{r.failed=true;MG.shake=.25;sfx.error();}}
function robotTap(x,y){if(y>380){let best=-1,bd=1e9;R_BTN.forEach(([bx],i)=>{const d=Math.abs(bx-x);if(d<bd){bd=d;best=i;}});if(bd<80)robotFix(best);}}

/* ---------- ROOF HOP ---------- */
const H_GRAV=1500,H_JUMP=-600,H_R=20;
function hopScene(c,scroll,t){skyFill(c,"#ff9a6a","#5b3bff",MH);
  c.fillStyle="rgba(255,240,200,.85)";c.beginPath();c.arc(MW-160,Y0()+110,46,0,7);c.fill();
  // far towers (slow) and near towers (faster)
  [[.15,"#5a4aa8",160,0],[.35,"#3f3590",230,1]].forEach(([k,col,hgt,lay])=>{for(let i=-1;i<12;i++){const span=120+lay*40,x=X0()+((i*span-scroll*k)%(VW()+span*2)+VW()+span*2)%(VW()+span*2)-span,h=hgt+((i*53+lay*31)%90);
    c.fillStyle=col;c.fillRect(x,MH-h-60,span-20,h+60);c.fillStyle=lay?"rgba(255,214,120,.45)":"rgba(255,214,120,.25)";for(let r=0;r<6;r++)for(let q=0;q<3;q++)if((i+r+q)%3)c.fillRect(x+10+q*((span-40)/3),MH-h-40+r*24,8,10);}});
  // flying cars far away
  for(let k=0;k<3;k++){const x=X0()+((k*360+t*90)%(VW()+200))-100,y=Y0()+90+k*40;c.fillStyle="#e9eef7";c.beginPath();c.ellipse(x,y,22,7,0,0,7);c.fill();c.fillStyle="rgba(89,224,255,.6)";c.beginPath();c.ellipse(x,y+8,18,3,0,0,7);c.fill();}}
function drawRoof(c,x,w,top,k){const col=["#4a5bd6","#6a3fc9","#2f7fc0"][k%3],g=c.createLinearGradient(0,top,0,MH+40);g.addColorStop(0,col);g.addColorStop(1,"#1a1450");c.fillStyle=g;c.fillRect(x,top,w,MH-top+40);
  c.fillStyle="rgba(255,255,255,.12)";c.fillRect(x,top,8,MH-top+40);
  c.fillStyle="rgba(255,214,120,.6)";for(let r=0;r<5;r++)for(let q=0;q<Math.floor(w/40);q++)if((k+r+q)%3)c.fillRect(x+14+q*40,top+40+r*36,16,18);
  c.fillStyle="#c9d2e3";c.fillRect(x-4,top-8,w+8,10);c.save();neonStroke(c,["#59e0ff","#ff4fd8","#7dff9b"][k%3],3,10);c.beginPath();c.moveTo(x-4,top-8);c.lineTo(x+w+4,top-8);c.stroke();c.restore();
  if(k%4===1){c.fillStyle="#8e98aa";c.fillRect(x+w*.6,top-30,30,22);c.fillStyle="#46516a";c.fillRect(x+w*.6+4,top-26,22,4);}
  if(k%5===3){c.strokeStyle="#c9d2e3";c.lineWidth=3;c.beginPath();c.moveTo(x+30,top-8);c.lineTo(x+30,top-60);c.stroke();c.fillStyle="#ff5f5f";c.beginPath();c.arc(x+30,top-62,4,0,7);c.fill();}}
function drawStar(c,x,y,t,s=1){c.save();c.translate(x,y+Math.sin(t*4+x)*4);c.scale(s,s);c.rotate(Math.sin(t*2)*.2);c.fillStyle="rgba(255,230,120,.3)";c.beginPath();c.arc(0,0,24,0,7);c.fill();
  c.fillStyle="#ffd23a";c.beginPath();for(let k=0;k<10;k++){const a=-Math.PI/2+k*Math.PI/5,r=k%2?7:17;c.lineTo(Math.cos(a)*r,Math.sin(a)*r);}c.closePath();c.fill();c.restore();}
function drawRunner(c,x,y,t,air,dizzy){c.save();c.translate(x,y);const col=skinHex(),run=air?0:Math.sin(t*22);
  [-1,1].forEach(sx=>{c.fillStyle=col;c.beginPath();c.ellipse(sx*9+run*sx*5,18,7,5,0,0,7);c.fill();});
  c.translate(0,-H_R+18);drawMiniJumpi(c,0,0,.62,col,dizzy?0:.6);c.restore();}
function hopInit(){const h=MG.info.hop;Object.assign(MG,{hp:h,hy:MG.info.items[0].top-8-H_R,hv:0,air:false,scroll:0,crashed:false,crashT:0,passed:0,caught:[]});}
const roofAt=(h,k,items)=>{const x0=h.first+k*h.span-(k===0?h.first:0),x1=h.first+(k+1)*h.span-items[k].gap;return [x0,x1];};
function hopJump(){if(!MG||MG.state!=="play"||MG.crashed||MG.air)return;MG.hv=H_JUMP;MG.air=true;sfx.hop();burst(MG.hp.jumperX,MG.hy+H_R,"#ffffff",5,80,200,3);}
function hopTick(dt,t){const c=mg2d,h=MG.hp,items=MG.info.items,jx=h.jumperX;
  if(!MG.crashed)MG.scroll=t*h.speed;
  const wx=MG.scroll+jx;   // the jumper's place in the course
  // which roof is under the jumper
  const k=Math.max(0,Math.floor((wx-h.first)/h.span)),[x0,x1]=wx<h.first?[-1e9,h.first+h.span-items[0].gap]:roofAt(h,k,items),onRoof=wx>=x0-H_R*.6&&wx<=x1+H_R*.6,top=wx<h.first?items[0].top:items[k].top;
  MG.hv+=H_GRAV*dt;MG.hy+=MG.hv*dt;
  if(onRoof&&!MG.crashed&&MG.hy+H_R>=top-8&&MG.hy+H_R-MG.hv*dt<=top+14&&MG.hv>=0){MG.hy=top-8-H_R;MG.hv=0;MG.air=false;}
  else if(onRoof&&!MG.crashed&&MG.hy+H_R>top+4){hopCrash(t);}   // ran into the side of a taller roof
  else MG.air=true;
  if(!MG.crashed&&MG.hy>MH+40)hopCrash(t);
  // a gap passed = a point (landing on the next roof)
  if(!MG.crashed&&!MG.air&&k>MG.passed&&wx>=h.first){MG.passed=k;addScore(1,jx,MG.hy-40);}
  const sh=MG.shake>0?(MG.shake-=dt,Math.sin(t*90)*8):0;c.save();c.translate(sh,0);hopScene(c,MG.scroll,t);
  const first=Math.max(0,Math.floor((MG.scroll+X0()-h.first)/h.span)-1),last=Math.min(items.length-1,Math.ceil((MG.scroll+X0()+VW()-h.first)/h.span)+1);
  if(MG.scroll+X0()<h.first)drawRoof(c,X0()-20,h.first-MG.scroll-X0()+20+h.span-items[0].gap,items[0].top,0);
  for(let q=Math.max(1,first);q<=last;q++){const [a,b]=roofAt(h,q,items);drawRoof(c,a-MG.scroll,b-a,items[q].top,q);}
  for(let q=Math.max(0,first);q<=last;q++){const it=items[q];if(!it.star||MG.caught.includes(q))continue;const sx=h.first+(q+1)*h.span-it.gap/2-MG.scroll,sy=Math.min(it.top,(items[q+1]||it).top)-90;
    drawStar(c,sx,sy,t);if(!MG.crashed&&Math.hypot(sx-jx,sy-MG.hy)<H_R+22){MG.caught.push(q);addScore(2,sx,sy-30);burst(sx,sy,"#ffd23a",14);}}
  drawRunner(c,jx,MG.hy,t,MG.air,MG.crashed);c.restore();
  if(MG.crashed&&t-MG.crashT>1.1&&MG.state==="play")endRound();}
function hopCrash(t){MG.crashed=true;MG.crashT=t;MG.shake=.4;MG.flash=.35;sfx.error();burst(MG.hp.jumperX,Math.min(MH,MG.hy),"#ffffff",14,220,400,5);}

// the start screens of the Future City games play by themselves
function futureDemo(dt,T,D){const c=mg2d,still=MG.state==="over"||MG.state==="ending"||MG.state==="starting"||MG.state==="count";
  if(MG.game==="drone"){droneScene(c,T*260,T);if(!still){if(T>D.nextT){D.nextT=T+.5;D.items.push({lane:Math.floor(Math.random()*5),y:D_TOP,k:Math.random()<.2?"gold":Math.random()<.25?"storm":"ring",v:300});}
      const tgt=D.items.find(it=>it.k!=="storm"&&it.y<D_Y);if(tgt)D.lane=tgt.lane;}
    D.dx+=(D_LANES[D.lane]-D.dx)*Math.min(1,dt*8);
    for(let i=D.items.length-1;i>=0;i--){const it=D.items[i];if(!still)it.y+=it.v*dt;if(it.y>MH+40){D.items.splice(i,1);continue;}const x=D_LANES[it.lane];it.k==="storm"?drawStorm(c,x,it.y,T):drawRing(c,x,it.y,it.k==="gold",T);}
    drawDrone(c,D.dx,D_Y+Math.sin(T*5)*3,T,0);return;}
  if(MG.game==="robot"){robotScene(c,T,still?0:T*150);if(!still&&T>D.nextT){D.nextT=T+1.4;D.bots.push({t:T,v:170,need:Math.floor(Math.random()*3),k:Math.random()<.2?"gold":"bot"});}
    for(let i=D.bots.length-1;i>=0;i--){const r=D.bots[i],x=-60+(T-r.t)*r.v;if(x>360&&!r.fixed)r.fixed=true;if(x>MW+80){D.bots.splice(i,1);continue;}drawRobot(c,x,R_BELT,r,T);}drawPartButtons(c,T,null);return;}
  // roof hop: an autopilot that jumps at the edge
  const h={first:520,span:300,speed:260,jumperX:170};if(!still)D.scroll+=h.speed*dt;const wx=D.scroll+h.jumperX,k=Math.max(0,Math.floor((wx-h.first)/h.span)),it=D.items[k%80],edge=h.first+(k+1)*h.span-it.gap;
  D.hv+=H_GRAV*dt;D.hy+=D.hv*dt;const top=D.items[k%80].top;if(D.hy+H_R>=top-8&&D.hv>=0&&wx<edge+4){D.hy=top-8-H_R;D.hv=0;D.air=false;if(edge-wx<40&&!still){D.hv=H_JUMP;D.air=true;}}
  if(D.hy>MH){D.hy=200;D.hv=0;}hopScene(c,D.scroll,T);
  for(let q=Math.max(1,k-1);q<k+4;q++){const iq=D.items[q%80],a=h.first+q*h.span,b=h.first+(q+1)*h.span-iq.gap;drawRoof(c,a-D.scroll,b-a,iq.top,q);if(iq.star)drawStar(c,h.first+(q+1)*h.span-iq.gap/2-D.scroll,Math.min(iq.top,D.items[(q+1)%80].top)-90,T);}
  if(k<1)drawRoof(c,X0()-20,h.first-D.scroll-X0()+20+h.span-D.items[0].gap,D.items[0].top,0);
  drawRunner(c,h.jumperX,D.hy,T,D.air,false);}
