if(testKey("mgtest"))window.__openMg=openMinigame;
/* ---------- the start screen: the game plays itself behind it ---------- */
function mgDemoInit(game){
  if(game==="fruit")return {bx:MW/2,target:MW/2,items:[],nextT:0,wob:0};
  if(game==="shell")return {pops:[],nextT:0};
  if(game==="dig"){const cells=Array(DCOLS*DROWS).fill(null);[[3,"chest"],[9,{hint:2}],[17,"gem"],[25,"coins"],[30,{hint:1}]].forEach(([i,v])=>cells[i]=typeof v==="string"?{item:v}:v);return {cells};}
  if(game==="drone")return {lane:2,dx:D_LANES[2],items:[],nextT:0,moveT:0};
  if(game==="robot")return {bots:[],nextT:0,t0:0};
  if(game==="rooftops")return {scroll:0,hy:272,hv:0,air:false,items:Array.from({length:80},(_,k)=>({gap:70+(k*37)%60,top:300+((k*53)%70),star:k%3===2}))};
  return {fy:MH*.45,fv:0,scroll:0,flapT:-9,items:Array.from({length:60},(_,k)=>({y:170+((k*97)%160),size:190,shell:k%3===1}))};
}
function mgDemo(dt,T){const c=mg2d,D=MG.demo;
  if(MG.game==="drone"||MG.game==="robot"||MG.game==="rooftops"){futureDemo(dt,T,D);return;}
  if(MG.state==="over"||MG.state==="ending"||MG.state==="starting"||MG.state==="count"){   // keep the last picture still
    if(MG.game==="fruit")fruitScene(T);else if(MG.game==="shell")shellScene(T);else if(MG.game==="dig")digScene(T,MG.cells||D.cells);else beachScene(c,MG.scroll||0,T);
    if(MG.game==="flap"&&MG.state!=="over")drawFlapJumpi(c,180,MH*.42+Math.sin(T*3)*8,1.15,0,Math.sin(T*8)>0);return;}
  if(MG.game==="fruit"){
    if(T>D.nextT){D.nextT=T+.5+Math.random()*.4;const f=FRUITS[Math.floor(Math.random()*4)];D.items.push({f,x:60+Math.random()*600,y:-20,vy:180+Math.random()*80,rot:0});}
    const near=D.items.reduce((a,b)=>!a||b.y>a.y?b:a,null);if(near)D.target=near.x;const ob=D.bx;D.bx+=(D.target-D.bx)*Math.min(1,dt*3);D.wob+=((D.bx-ob)/Math.max(dt,.001)*.01-D.wob)*Math.min(1,dt*8);
    fruitScene(T);for(let i=D.items.length-1;i>=0;i--){const it=D.items[i];it.y+=it.vy*dt;it.rot+=dt;if(it.y>MH-90&&Math.abs(it.x-D.bx)<60){D.items.splice(i,1);burst(it.x,MH-100,"#ffffff",6);continue;}if(it.y>MH+20)D.items.splice(i,1);else drawFruit(c,it.f,it.x,it.y,1,it.rot);}
    drawMiniJumpi(c,D.bx,MH-72,.95,skinHex(),Math.max(-1,Math.min(1,D.wob)));drawBasket(c,D.bx,MH-78,D.wob);}
  else if(MG.game==="shell"){shellScene(T);
    if(T>D.nextT){D.nextT=T+.45;const h=Math.floor(Math.random()*12),k=Math.random()<.15?"pearl":Math.random()<.2?"crab":"shell";D.pops.push({x:HOLES[h][0],y:HOLES[h][1],k,t:0,life:1.2});}
    for(let i=D.pops.length-1;i>=0;i--){const p=D.pops[i];p.t+=dt;if(p.t>p.life){D.pops.splice(i,1);continue;}const s=p.t<.15?p.t/.15:p.t>p.life-.15?(p.life-p.t)/.15:1;drawShellThing(c,{...p,y:p.y+(1-s)*20},Math.max(.01,s));}}
  else if(MG.game==="dig"){digScene(T,D.cells);}
  else{D.scroll+=200*dt;beachScene(c,D.scroll,T);
    // a simple autopilot: bounce toward the next gap
    const f={first:800,gap:270,half:40},k=Math.max(0,Math.floor((D.scroll-f.first+180-f.half)/f.gap)+1),it=D.items[k%60];
    D.fv+=FL.grav*dt;if(D.fy>it.y+20&&D.fv>0){D.fv=FL.up;D.flapT=T;}D.fy+=D.fv*dt;D.fy=Math.max(40,Math.min(FL.ground-30,D.fy));
    for(let j=Math.max(0,k-2);j<k+4;j++){const x=f.first+j*f.gap-D.scroll,itj=D.items[j%60];if(x<X0()-100||x>X0()+VW()+100)continue;
      drawBoard(c,x-f.half,itj.y-95,80,boardCol(j),true);drawBoard(c,x-f.half,itj.y+95,80,boardCol(j+2),false);if(itj.shell)drawGoldShell(c,x,itj.y,1,T);}
    drawFlapJumpi(c,180,D.fy,1.15,Math.max(-.5,Math.min(1.2,D.fv/700)),T-D.flapT<.18);}
}


